/* GeoSR editorial homepage — concept imagery is replaced through documented media slots */
const expertiseScenes = [
  {k:'관측·공간정보',e:'Observation & spatial information',leadK:'현장의 기준을 세우다',leadE:'Establish a field reference',bodyK:'육상·수로 측량과 해양 관측으로 공간의 기준 자료를 확보합니다',bodyE:'Land, hydrographic and marine observations establish a spatial reference',image:'coastal-survey-source.png',source:true,tagsK:['육상 측량','수로·해양 관측','공간정보'],tagsE:['Land surveys','Hydrographic & marine observation','Spatial information'],page:'equipment'},
  {k:'환경·생태 분석',e:'Environmental & ecological analysis',leadK:'환경의 상태를 확인하다',leadE:'Read environmental conditions',bodyK:'수질·퇴적물과 생태 조사 자료를 함께 검토해 환경 상태를 평가합니다',bodyE:'Water, sediment and ecological observations are reviewed together to assess environmental conditions',image:'coastal-survey-source.png',source:false,tagsK:['수질·퇴적물','생태 조사','환경 평가'],tagsE:['Water & sediment','Ecological surveys','Environmental assessment'],page:'business',params:{id:84}},
  {k:'유역·연안 모델링',e:'Watershed & coastal modelling',leadK:'변화의 경로를 살피다',leadE:'Trace environmental change',bodyK:'지형과 관측 자료를 바탕으로 유역과 연안의 흐름과 변화를 분석합니다',bodyE:'Terrain and observations support analysis of change across watersheds and coasts',image:'coastal-model-v3.png',source:false,tagsK:['유역 모델','연안 모델','영향 분석'],tagsE:['Watershed models','Coastal models','Impact analysis'],page:'business',params:{id:46}},
  {k:'위성·AI 해석',e:'Satellite & AI interpretation',leadK:'더 넓은 맥락을 읽다',leadE:'Read a wider context',bodyK:'위성·관측 자료의 패턴과 유효 영역을 비교해 환경 변화를 해석합니다',bodyE:'Satellite and observation data are compared to interpret environmental change',image:'satellite-layers-v3.png',source:false,tagsK:['위성영상','환경 AI','변화 해석'],tagsE:['Satellite imagery','Environmental AI','Change interpretation'],page:'business',params:{id:61}}
];

function expertisePanel(i=0){const d=expertiseScenes[i];return `<div class="expertise-photo" data-production-slot="expertise-${i+1}"><img src="assets/${d.image}" alt="${E(T(d.k,d.e))} — ${d.source?T('GeoSR 원본 자료','GeoSR source material'):T('영상 가안','film concept')}" loading="lazy"><span class="media-note">${d.source?T('GEOSR 현장 자료','GEOSR FIELD REFERENCE'):T('기술 연출 가안 · 실제 해석 결과 아님','VISUAL CONCEPT · NOT A VERIFIED ANALYSIS')}</span></div><div class="expertise-details"><span class="scene-index">0${i+1} / 04</span><h3>${T(d.leadK,d.leadE)}</h3><p>${T(d.bodyK,d.bodyE).replaceAll('\n','<br>')}</p><div class="expertise-tags">${(en?d.tagsE:d.tagsK).map(t=>`<span>${t}</span>`).join('')}</div>${A(U(d.page,d.params||{}),'관련 기술 보기','Explore the technology','plain-arrow')}</div>`}

function home(){return `
<section class="landscape-hero" data-production-slot="geosr-hero" data-film-slot="geosr-hero" data-motion-lab-hero>
 <div class="landscape-film" data-production-slot="geosr-hero" data-film-slot="geosr-hero" data-higgsfield-slot="geosr-hero" aria-label="${T('메인 영상 자리','Main film slot')}"><div class="landscape-film-fallback"><span>${T('영상 제작 준비 중','FILM IN PREPARATION')}</span></div></div>
 <div class="landscape-vignette"></div>
 <div class="hero-edition"><span>GEOSYSTEM RESEARCH</span><span>${T('현장·연구·분석','FIELD · RESEARCH · ANALYSIS')}</span></div>
 <div class="landscape-title"><p>ENVIRONMENTAL INTELLIGENCE</p><h1>Environmental<br>Intelligence</h1></div>
 <div class="landscape-caption"><p>${T('현장에서 시작해<br>환경의 변화를 해석합니다','From field observation<br>to environmental insight')}</p><a class="round-explore" href="#expertise" aria-label="${T('기술 소개로 이동','Explore our expertise')}">↓</a></div>
 <div class="landscape-footer"><span>GEOSR / FILM SLOT</span><span class="landscape-film-status">${T('영상 제작 준비 중','FILM IN PREPARATION')}</span><button type="button" class="landscape-motion" aria-pressed="false">${T('모션 정지','Pause motion')} Ⅱ</button></div>
</section>
<section class="science-intro" id="expertise">
 <div class="science-label"><span class="tiny-index">01 — GEOSR EXPERTISE</span><p>${T('현장에서 시작해<br>더 넓은 해답으로','From the field<br>to a bigger picture')}</p></div>
 <div class="science-statement"><h2>${T('현장을 관측하고<br><span>환경의 변화를 예측합니다</span>','Observe the present<br><span>Understand what comes next</span>')}</h2><div class="science-intro-bottom"><p>${T('육상과 하천에서 연안과 해양까지<br>조사와 분석에 수치모델과 AI를 더해<br>복잡한 환경 문제를 풀어갑니다','From land and rivers to coasts and oceans<br>We connect field research with modelling and AI<br>to address complex environmental challenges')}</p>${A(U('business'),'기술과 솔루션','Our expertise','ink-link')}</div></div>
</section>
<section class="field-story" aria-label="${T('연구 흐름','Research flow')}" data-research-flow>
 <div class="field-stage">
  <div class="field-story-top"><span>RESEARCH FLOW</span><span class="field-count">01 / 04</span></div>
  <div class="field-frames">${expertiseScenes.map((d,i)=>`<div class="field-frame field-frame-${i+1} ${i===0?'is-active':''}" data-frame="${i}" data-film-slot="expertise-${i+1}" data-film-active="${i===0}"></div>`).join('')}</div>
  <div class="field-shade"></div>
  <div class="field-copy">${expertiseScenes.map((d,i)=>`<article class="field-chapter ${i===0?'is-active':''}" data-chapter="${i}" ${i?'inert':''}><span>0${i+1} / ${d.e.toUpperCase()}</span><h2>${T(d.k,d.e)}</h2><p>${T(d.bodyK,d.bodyE).replaceAll('\n','<br>')}</p>${A(U(d.page,d.params||{}),'관련 기술 살펴보기','Explore this discipline','field-link')}</article>`).join('')}</div>
  <div class="field-navigator field-flow" role="group" aria-label="${T('연구 흐름 선택','Choose a research flow')}">${expertiseScenes.map((d,i)=>`<button type="button" data-chapter-go="${i}" aria-pressed="${i===0}"><span>0${i+1}</span>${T(d.k,d.e)}<i></i></button>`).join('')}</div>
  <small class="field-disclaimer">${T('연구 흐름을 요약한 일반 설명 · 실제 해석 결과 아님','GENERAL RESEARCH FLOW · NOT VERIFIED ANALYSIS')}</small>
 </div>
</section>
<section class="digital-section" id="platforms">
 <div class="digital-title"><span class="tiny-index">02 — DIGITAL PLATFORMS</span><h2>${T('기술을 손끝에','Intelligence<br>in your hands')}</h2><p>${T('GeoSR의 연구가 실제로 작동하는 곳','Where our research comes to life')}</p></div>
 <article class="digital-feature ax-feature"><div class="digital-copy"><span class="tiny-index">APPLIED INTELLIGENCE</span><h3>AX <em class="ax-name">Platform</em></h3><p>${T('탐지에서 예측과 모니터링까지','Detection · Prediction · Monitoring')}</p><div class="digital-description">${T('해양·환경 분야의 문제를 해결하는<br>목적별 응용 플랫폼을 소개합니다','Discover specialised applications<br>for marine and environmental challenges')}</div>${A(U('ax-platform'),'9개 플랫폼 살펴보기','Explore 9 platforms','pill-link')}</div>${axFilmReel()}</article>
 <article class="digital-feature dap-feature"><div class="digital-copy"><span class="tiny-index">EARTH DATA PLATFORM</span><h3>GeoDAP</h3><p>Earth Data Intelligence</p><div class="digital-description">${T('관측과 모델에서 위성 데이터까지<br>지구환경 데이터를 한곳에서 탐색합니다','Explore observations, models<br>and satellite data in one place')}</div><a class="pill-link" href="https://www.geo-dap.com/" target="_blank" rel="noopener">${T('GeoDAP 바로가기','Open GeoDAP')} <span>↗</span></a></div><a class="digital-screen dap-screen" href="https://www.geo-dap.com/" target="_blank" rel="noopener" aria-label="${T('GeoDAP 새 창에서 열기','Open GeoDAP in a new tab')}"><div class="screen-top"><span>GEODAP / EARTH DATA</span><span>${T('독립 서비스','INDEPENDENT PLATFORM')}</span></div><img src="assets/platform-geodap.png" alt="${T('GeoDAP 지구환경 데이터 탐색 화면','GeoDAP Earth data interface')}" loading="lazy"></a></article>
</section>
${credentialGallery()}
<section class="research-editorial-section new-research"><div class="section-kicker"><span>04 / RESEARCH & NEWS</span>${A(U('research'),'전체보기','View all','plain-arrow')}</div><div class="research-title-row"><h2>${T('연구는 계속됩니다','Research<br>moves forward')}</h2><p>${T('현장에서 전하는 새로운 소식','New perspectives from the field')}</p></div><div class="editorial-records">${[posts[1],posts[3],posts[2]].map((p,i)=>`<a class="editorial-record" href="${U(p[1]==='notice'?'news':'research',{id:p[0]})}"><span class="editorial-number">0${i+1}</span><div><span class="editorial-type">${T(...types.find(t=>t[0]===p[1]).slice(1))}</span><h3>${E(T(p[3],p[4]))}</h3></div><time>${p[2].replaceAll('-',' / ')}</time><span class="editorial-arrow">↗</span></a>`).join('')}</div></section>`}


function axFilmReel(){
 const scenes=[
  {id:'detect',name:'Detect',ko:'탐지',k:'위성영상에서 시설물을 탐지하는 과정',e:'Detecting facilities in satellite imagery',platforms:'SATELLITE FACILITY DETECTION'},
  {id:'predict',name:'Predict',ko:'예측',k:'태풍 시나리오에 따른 해수면과 연안 침수의 변화',e:'Sea-level and coastal inundation changes under typhoon scenarios',platforms:'FLOOD 3D · STORM SURGE · EXTREME SEA LEVEL'},
  {id:'monitor',name:'Monitor',ko:'모니터링',k:'관측 지점에서 해역까지 해양환경을 살피는 과정',e:'Following marine conditions from observation stations to regional waters',platforms:'OCEAN BUOY · OCEAN ENVIRONMENT · RIP CURRENT'}
 ];
 return `<div class="ax-reel-wrap"><div class="ax-reel"><div class="ax-reel-heading"><span>AX / IN FOCUS</span><span>${T('영상 제작 대기','FILM IN PREPARATION')}</span></div><div class="ax-reel-viewport">${scenes.map((s,i)=>`<section class="ax-reel-panel" id="ax-panel-${s.id}" role="tabpanel" aria-labelledby="ax-tab-${s.id}" tabindex="0" data-film-slot="ax-${s.id}" data-motion-mode="${["slow-push","lateral-pan","detail-focus"][i]}" data-film-active="${i===0}" ${i?'hidden inert':''}><div class="ax-reel-placeholder"><small>0${i+1} / ${T('장면 구성안','SCENE OUTLINE')}</small><strong>${s.name}</strong><p>${T(s.k,s.e)}</p></div><div class="ax-reel-platforms">${s.platforms}</div><button class="ax-film-toggle" type="button" data-film-toggle="ax-${s.id}" aria-label="${T('영상 재생 또는 일시정지','Play or pause film')}" aria-pressed="false" hidden>Ⅱ</button></section>`).join('')}</div><div class="ax-reel-tabs" role="tablist" aria-label="${T('AX 영상 장면','AX film scenes')}">${scenes.map((s,i)=>`<button type="button" id="ax-tab-${s.id}" role="tab" aria-controls="ax-panel-${s.id}" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-ax-scene="${i}"><span>0${i+1}</span>${T(s.ko,s.name)}</button>`).join('')}</div></div><p class="ax-reel-note">${T('각 플랫폼의 실제 기능을 바탕으로 구성한 영상 자리입니다','Film slots based on the actual functions of each platform')}</p></div>`;
}

function credentialGallery(){return `<section class="credential-section" id="credentials" aria-labelledby="credential-heading"><div class="section-kicker"><span>03 / PATENTS & CERTIFICATIONS</span><span>RESEARCH THAT BUILDS</span></div><div class="credential-intro"><h2 id="credential-heading">Built on<br><span>research</span></h2><div><p>${T('GeoSR의 특허와 기술 인증','Patents and certifications from GeoSR')}</p><p class="muted">${T('쌓아온 기술을 기록으로 확인하세요','Explore the records behind our expertise')}</p><div class="gallery-controls"><button type="button" data-gallery-step="-1" aria-label="${T('이전 자료','Previous document')}">←</button><span id="credential-status" aria-live="polite">01 / 07</span><button type="button" data-gallery-step="1" aria-label="${T('다음 자료','Next document')}">→</button></div></div></div><div class="credential-rail" tabindex="0" role="region" aria-label="${T('인증서·특허 가로 갤러리','Horizontal patent and certification gallery')}" aria-describedby="credential-hint"><div class="credential-loading">${T('자료를 불러오는 중','Loading documents')}</div></div><div class="credential-bottom"><p id="credential-hint">${T('좌우로 넘겨보기 · 자료를 선택하면 확대됩니다','Swipe or use the arrows · Select a document to enlarge')}</p><a href="${U('company')}#credential-library">${T('인증·면허·지식재산권 전체보기','Explore the document collection')} ↗</a></div></section><dialog id="credential-dialog" aria-labelledby="credential-dialog-title"><div class="document-modal-head"><h2 id="credential-dialog-title"></h2><button type="button" data-close-document aria-label="${T('닫기','Close')}">×</button></div><img alt=""><div class="document-modal-foot"><p>${T('기존 홈페이지에 공개된 자료의 사본','A copy of the record published on the original website')}</p><a target="_blank" rel="noopener">${T('문서 사본 열기','Open document copy')} ↗</a></div></dialog>`}

function modernFooter(){return `<section class="contact-editorial"><div class="contact-editorial-top"><p class="eyebrow">CONNECT WITH GEOSR</p><span>${T('사업과 연구의 다음 파트너','YOUR NEXT RESEARCH & ENGINEERING PARTNER')}</span></div><a href="${U('contact')}" class="contact-statement"><h2>Let’s move<br><span>forward</span></h2><span aria-hidden="true">↗</span></a><div class="contact-editorial-bottom"><p>${T('사업·기술 문의 및 연구 협력','Projects, technology enquiries and research partnerships')}</p><a href="mailto:admin@geosr.com">admin@geosr.com ↗</a></div></section><footer class="site-footer"><div class="footer-information"><div><a class="brand" href="${U('index')}"><img src="assets/logo.png" alt="GeoSR"></a><p>${T('지오시스템리서치','GeoSystem Research Corporation')}<br>${T('경기도 군포시 엘에스로 172 한림휴먼타워 306호','306 Hanlim Human Tower, 172 LS-ro, Gunpo-si, Korea')}</p><a href="tel:+823151805700">+82 31 5180 5700</a></div><div class="footer-navigation">${nav.map(n=>A(U(n[0]),n[1],n[2])).join('')}${A('https://www.geo-dap.com/','GeoDAP','GeoDAP')}</div><div class="footer-meta"><span>© GEOSYSTEM RESEARCH</span><p>${T('디자인 목업<br>생성 이미지는 영상 제작을 위한 가안입니다','DESIGN PROTOTYPE<br>Generated imagery represents proposed films')}</p>${A(U('equipment'),'관측·장비','Observation & equipment')}</div></div><div class="footer-wordmark" aria-hidden="true">GeoSR<span>®</span></div></footer>`}
